import type { Catalog } from "./en";

/**
 * తెలుగు — Telugu. Typed against en.ts, so a missing key won't compile.
 *
 * COMPLETE: all 4,894 keys, translated by hand, not by machine. It was 460
 * keys (20.7%) two passes ago — the `core` block plus part of `chrome` — and
 * the rest fell back to English, so a woman who chose Telugu got Telugu tabs
 * above English screens.
 *
 * The last 1,550 are the module data: the sections, cards, steps and tips
 * that live in `components/ux/*​/data.ts` rather than in a component. They
 * reach the screen through `useTranslated()`, which matches a string by its
 * English text — so these entries are load-bearing in a way the others are
 * not, and a careless edit to one silently returns English.
 *
 * Only prose is in here. Slugs, image names, font stacks, CSS classes and the
 * ids the API expects (`back-pain`, `not-started`, `scene-woman-meditating`)
 * were pulled back out of the catalogue: `useTranslated` walks every field it
 * is handed, so an id left in here would be translated on its way to the
 * server and quietly stop matching.
 *
 * The register, which is the whole point:
 *
 * - **మీరు, never నువ్వు.** Microsoft's Telugu guide is explicit, and its own
 *   shipped strings use మీరు 15 times and నీవు none. To a woman, the familiar
 *   pronoun from an institution is what an employer uses on a domestic worker.
 * - **-ండి on every imperative** — చేయండి, ఎంచుకోండి, నొక్కండి.
 * - **వ్యావహారికం, not గ్రాంథికం.** Everyday spoken Telugu. This is Gidugu
 *   Ramamurthy's argument, settled in 1933: the literary register "did not
 *   promote the skills necessary either for understanding or communicating
 *   effectively in real life situations." Half this app's readers left school
 *   early; officialese is a second gate on the same door.
 * - **The loanword where the loanword has won** — ఫోన్, ఈమెయిల్, పాస్‌వర్డ్,
 *   ఆర్డర్, బ్యాంక్. Coining Sanskritised replacements is the CSTT habit and
 *   it is exactly what makes translated apps unreadable.
 * - **No దయచేసి.** The English does not say "please" either; in Telugu it
 *   reads servile and costs width at 390px.
 * - One word for one thing: circle is గుంపు (not సర్కిల్), shop is దుకాణం,
 *   period is నెలసరి, Sakhi is సఖి in her own script.
 *
 * Machine-verified before shipping: all keys present, every {placeholder}
 * intact, every value in Telugu script. See [[ADR-016]].
 */
