  "reach.itIsAndItIsWritten": "నిజమైనదే, పైగా రాసి ఉంది. తొమ్మిది నెలలు, ప్రతి నెలా సంపాదన, ఎవరైనా చెక్ చేసుకోగలిగే స్టేట్‌మెంట్.",
