  "reach.womenFromHereByNameAnd": "ఇక్కడి మహిళలే, పేరుతో సహా — పైగా వాళ్లను కలవవచ్చు. గుంపు అంటే ఫోన్లో ఉన్న అపరిచితులు కాదు.",
  "reach.yourCircleByName": "మీ గుంపు, పేరుతో సహా",
  "reach.whatIfYouAreCheated": "“మోసపోతే ఏం చేస్తావు?”",
  "reach.theMoneyGoesToYourOwn": "డబ్బు మీ సొంత బ్యాంక్ ఖాతాలోకే వెళ్తుంది, ఏ యాప్‌లోకీ కాదు. పైగా పని తీసుకునే ముందే ప్రతి కొనుగోలుదారు రికార్డు అక్కడే ఉంటుంది.",
